-- Official Topps NOW #122; guarded catalogue-only append.
begin; set local lock_timeout='5s';
lock table public.catalogue_sets,public.catalogue_subsets,public.catalogue_cards,public.catalogue_variants,public.catalogue_sources,public.catalogue_parallel_rules,public.collection_items,public.reference_images in share row exclusive mode;
create temporary table before_catalogue_sets on commit drop as select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end as row from public.catalogue_sets t;
create temporary table before_catalogue_subsets on commit drop as select case when t.set_id='2026-topps-now-wwe' and t.subset_code='BASE' then to_jsonb(t)-'card_count' else to_jsonb(t) end as row from public.catalogue_subsets t;
create temporary table before_catalogue_cards on commit drop as select to_jsonb(t) as row from public.catalogue_cards t;
create temporary table before_catalogue_variants on commit drop as select to_jsonb(t) as row from public.catalogue_variants t;
create temporary table before_catalogue_sources on commit drop as select to_jsonb(t) as row from public.catalogue_sources t;
create temporary table before_catalogue_parallel_rules on commit drop as select to_jsonb(t) as row from public.catalogue_parallel_rules t;
create temporary table before_collection_items on commit drop as select to_jsonb(t) as row from public.collection_items t;
create temporary table before_reference_images on commit drop as select to_jsonb(t) as row from public.reference_images t;
do $$ begin
      if (select count(*) from public.catalogue_cards where set_id='2026-topps-now-wwe') not in (143,144)
      or (select count(*) from public.catalogue_variants where set_id='2026-topps-now-wwe') not in (227,233)
      or exists(select 1 from public.catalogue_cards where set_id='2026-topps-now-wwe' and card_number in ('122') and id<>'2026-TNWWE-BASE-'||card_number)
      or exists(select 1 from public.catalogue_cards where set_id='2026-topps-now-wwe' and checklist_order between 144 and 144 and id not in ('2026-TNWWE-BASE-122'))
      or exists(select 1 from public.catalogue_variants where set_id='2026-topps-now-wwe' and variant_order between 228 and 233 and card_id not in ('2026-TNWWE-BASE-122'))
      then raise exception 'Unexpected annual baseline'; end if;
    end $$;
do $$ begin
 if exists(select 1 from public.catalogue_cards t join jsonb_populate_recordset(null::public.catalogue_cards,'[{"id":"2026-TNWWE-BASE-122","set_id":"2026-topps-now-wwe","checklist_order":144,"category":"Base","subset_code":"BASE","card_number":"122","display_name":"IYO SKY","subject_1":"IYO SKY","subject_2":null,"roster":null,"rookie":false,"parallel_group":"BASE","image_status":"Missing","pricing_status":"Unpriced","source_url":"https://www.topps.com/products/iyo-sky-2026-wwe-topps-now-r-card-122","notes":"US and UK on-sale window 17–20 November 2026; UK closing date still shown in current Specs, US sold-out page now omits closing date. US shipping estimate 10–15 business days; UK 15–20 business days after expiry. Topps advertises /5 and 1/1 Autograph Redemption cards; printed autograph codes unverified. Official product number verified; physical back and final print run pending. Conditional Chrome/Opal editions excluded."}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.checklist_order is distinct from e.checklist_order or t.category is distinct from e.category or t.subset_code is distinct from e.subset_code or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.subject_1 is distinct from e.subject_1 or t.subject_2 is distinct from e.subject_2 or t.roster is distinct from e.roster or t.rookie is distinct from e.rookie or t.parallel_group is distinct from e.parallel_group or t.image_status is distinct from e.image_status or t.pricing_status is distinct from e.pricing_status or t.source_url is distinct from e.source_url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_cards row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_cards(id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes) select id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes from jsonb_populate_recordset(null::public.catalogue_cards,'[{"id":"2026-TNWWE-BASE-122","set_id":"2026-topps-now-wwe","checklist_order":144,"category":"Base","subset_code":"BASE","card_number":"122","display_name":"IYO SKY","subject_1":"IYO SKY","subject_2":null,"roster":null,"rookie":false,"parallel_group":"BASE","image_status":"Missing","pricing_status":"Unpriced","source_url":"https://www.topps.com/products/iyo-sky-2026-wwe-topps-now-r-card-122","notes":"US and UK on-sale window 17–20 November 2026; UK closing date still shown in current Specs, US sold-out page now omits closing date. US shipping estimate 10–15 business days; UK 15–20 business days after expiry. Topps advertises /5 and 1/1 Autograph Redemption cards; printed autograph codes unverified. Official product number verified; physical back and final print run pending. Conditional Chrome/Opal editions excluded."}]'::jsonb) on conflict do nothing;

do $$ begin
 if exists(select 1 from public.catalogue_variants t join jsonb_populate_recordset(null::public.catalogue_variants,'[{"id":"2026-TNWWE-BASE-122-IDENTITY","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":228,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Checklist identity","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Unnumbered checklist identity; print run is not a serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-GOLD-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":229,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Gold Foil","serial_cap":50,"serial_exact":"/50","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-ORANGE-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":230,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Orange Foil","serial_cap":25,"serial_exact":"/25","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-BLACK-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":231,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Black Foil","serial_cap":10,"serial_exact":"/10","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-RED-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":232,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Red Foil","serial_cap":5,"serial_exact":"/5","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-FOILFRACTOR","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":233,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"FoilFractor","serial_cap":1,"serial_exact":"1/1","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.card_id is distinct from e.card_id or t.variant_order is distinct from e.variant_order or t.subset is distinct from e.subset or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_variants row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_variants(id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from jsonb_populate_recordset(null::public.catalogue_variants,'[{"id":"2026-TNWWE-BASE-122-IDENTITY","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":228,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Checklist identity","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Unnumbered checklist identity; print run is not a serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-GOLD-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":229,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Gold Foil","serial_cap":50,"serial_exact":"/50","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-ORANGE-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":230,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Orange Foil","serial_cap":25,"serial_exact":"/25","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-BLACK-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":231,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Black Foil","serial_cap":10,"serial_exact":"/10","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-RED-FOIL","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":232,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"Red Foil","serial_cap":5,"serial_exact":"/5","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-BASE-122-FOILFRACTOR","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-BASE-122","variant_order":233,"subset":"Regular","card_number":"122","display_name":"IYO SKY","parallel":"FoilFractor","serial_cap":1,"serial_exact":"1/1","exclusive_note":null,"numbering_note":"Card-specific Topps product listing names this foil and serial cap.","verification_status":"Official Topps product listing"}]'::jsonb) on conflict do nothing;

do $$ begin
 if exists(select 1 from public.catalogue_sources t join jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-TNWWE-BASE-122-SOURCE","set_id":"2026-topps-now-wwe","source":"Topps official product page","purpose":"Card 122 identity and advertised editions","url":"https://www.topps.com/products/iyo-sky-2026-wwe-topps-now-r-card-122","notes":"US and UK on-sale window 17–20 November 2026; UK closing date still shown in current Specs, US sold-out page now omits closing date. US shipping estimate 10–15 business days; UK 15–20 business days after expiry. Topps advertises /5 and 1/1 Autograph Redemption cards; printed autograph codes unverified. Official product number verified; physical back and final print run pending. Conditional Chrome/Opal editions excluded."}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-TNWWE-BASE-122-SOURCE","set_id":"2026-topps-now-wwe","source":"Topps official product page","purpose":"Card 122 identity and advertised editions","url":"https://www.topps.com/products/iyo-sky-2026-wwe-topps-now-r-card-122","notes":"US and UK on-sale window 17–20 November 2026; UK closing date still shown in current Specs, US sold-out page now omits closing date. US shipping estimate 10–15 business days; UK 15–20 business days after expiry. Topps advertises /5 and 1/1 Autograph Redemption cards; printed autograph codes unverified. Official product number verified; physical back and final print run pending. Conditional Chrome/Opal editions excluded."}]'::jsonb) on conflict do nothing;

update public.catalogue_subsets set card_count=122 where set_id='2026-topps-now-wwe' and subset_code='BASE' and card_count=121;
    update public.catalogue_sets set card_count=144,variant_count=233,updated_at=now() where id='2026-topps-now-wwe' and (card_count,variant_count)=(143,227);
    do $$ begin
      if (select count(*) from public.catalogue_cards where set_id='2026-topps-now-wwe')<>144
      or (select count(*) from public.catalogue_variants where set_id='2026-topps-now-wwe')<>233
      or (select count(*) from public.catalogue_cards where set_id='2026-topps-now-wwe' and subset_code='BASE')<>122
      or not exists(select 1 from public.catalogue_subsets where set_id='2026-topps-now-wwe' and subset_code='BASE' and card_count=122)
      or not exists(select 1 from public.catalogue_sets where id='2026-topps-now-wwe' and card_count=144 and variant_count=233)
      then raise exception 'Annual count validation failed'; end if;
    end $$;
do $$ begin if exists(select row from before_catalogue_sets except all select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end from public.catalogue_sets t) then raise exception 'Existing catalogue_sets rows changed'; end if; end $$;
do $$ begin if exists(select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end from public.catalogue_sets t except all select row from before_catalogue_sets) then raise exception 'Unexpected catalogue_sets rows'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_subsets except all select case when t.set_id='2026-topps-now-wwe' and t.subset_code='BASE' then to_jsonb(t)-'card_count' else to_jsonb(t) end from public.catalogue_subsets t) then raise exception 'Existing catalogue_subsets rows changed'; end if; end $$;
do $$ begin if exists(select case when t.set_id='2026-topps-now-wwe' and t.subset_code='BASE' then to_jsonb(t)-'card_count' else to_jsonb(t) end from public.catalogue_subsets t except all select row from before_catalogue_subsets) then raise exception 'Unexpected catalogue_subsets rows'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t) then raise exception 'Existing catalogue_cards rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t) then raise exception 'Existing catalogue_variants rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t) then raise exception 'Existing catalogue_sources rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_parallel_rules except all select to_jsonb(t) from public.catalogue_parallel_rules t) then raise exception 'Existing catalogue_parallel_rules rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.catalogue_parallel_rules t except all select row from before_catalogue_parallel_rules) then raise exception 'Unexpected catalogue_parallel_rules rows'; end if; end $$;
do $$ begin if exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t) then raise exception 'Existing collection_items rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items) then raise exception 'Unexpected collection_items rows'; end if; end $$;
do $$ begin if exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t) then raise exception 'Existing reference_images rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images) then raise exception 'Unexpected reference_images rows'; end if; end $$;
select 'NOW 122 verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.collection_items) as collections;
commit;
